def backfill_labels(apps, schema_editor):
    Taxonomy = apps.get_model("photolith", "Taxonomy")

    for tx in Taxonomy.objects.filter(key="maturity", identifier__in=LABELS.keys()):
        tx.str_en = LABELS[tx.identifier]
        tx.str_is = LABELS[tx.identifier]
        tx.save()


def restore_unknown(apps, schema_editor):
    Taxonomy = apps.get_model("photolith", "Taxonomy")

    for tx in Taxonomy.objects.filter(key="maturity", identifier__in=LABELS.keys()):
        if tx.str_en == LABELS[tx.identifier]:
            tx.str_en = "Unknown"
            tx.str_is = ""
            tx.save()


